import {sleepSection,bindSleepImport} from './sleep-ui.mjs';
import {mealPhotoSection,bindMealPhotos,mealArchive,restoreMealArchive} from './meal-photos.mjs';
import {DEFAULT_PLAN,LABELS,label,today,plusDays,dateOK,copy,activeTrial,startTrial,startSession,entry,writeEntry,exerciseEntryId,blankRows,sessions,sessionExercises,hasActual,removeEntry,changePlan,trialSummary,trialMarkdown} from './journal.mjs';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=id=>document.getElementById(id);
function input(key,title,value,type='text',extra=''){return `<label class="journal-field"><span>${title}</span><input class="text-input" data-field="${key}" type="${type}" value="${esc(value??'')}" ${type==='number'?'min="0" max="100000" step="any"':''} ${type==='text'?'maxlength="200"':''} ${extra}></label>`;}
function area(key,title,value,placeholder=''){return `<label class="journal-field"><span>${title}</span><textarea class="text-input" data-field="${key}" rows="3" maxlength="6000" placeholder="${esc(placeholder)}">${esc(value??'')}</textarea></label>`;}
function select(key,title,value,group){return `<label class="journal-field"><span>${title}</span><select class="text-input" data-field="${key}"><option value="">未填写</option>${Object.entries(LABELS[group]).map(([v,t])=>`<option value="${v}" ${v===value?'selected':''}>${t}</option>`).join('')}</select></label>`;}
const mealGuide=()=>`<details class="journal-guide"><summary>饮食试行安排与替换</summary><p>目标：吃得足够、支持训练和恢复，先不主动减重。预算分配需要用实际购买验证。</p><div class="meal-guide"><p><b>早餐 · 约6元</b><br>2颗鸡蛋＋红薯／燕麦／馒头＋约300毫升牛奶。</p><p><b>午餐 · 约12元</b><br>米饭／面条＋一掌心肉或鱼＋1–2拳蔬菜。外食不足时补鸡蛋、豆腐、鸡肉或部分自带。</p><p><b>晚餐 · 约10元</b><br>正常份量的主食＋一掌心肉或鱼＋约200克豆腐＋1–2拳蔬菜。肉已较多时，豆腐可移到午餐。</p><p><b>水果 · 约2元</b><br>当季水果约200–350克。咖啡费用也计入预算，优先自备。</p></div><p>主食以吃饱、支持活动为起点，不因加奶或豆腐就自动删掉原有主食。训练或打球后明显更饿，可加主食或小加餐并记录。</p><p>先详记3个代表日：普通日、力量训练日、羽毛球日。注明肉类生／熟、包装总量和实际食用量；不直接把包装克数当作纯肉量。</p><p>咖啡固定产品和粉量；杯子水量不能代表咖啡因剂量。结合睡眠、胃部和心悸等反馈调整，不用咖啡代替食物。</p><p class="hint">此模板不能保证具体热量或蛋白质达标。核对实际食物后再决定调整。<a href="https://dg.cnsoc.org/article/04/70JvPbFmTlyZbjoO67LeRg.html" target="_blank" rel="noopener">膳食指南参考</a></p></details>`;
export function mountJournal({getState,transact,notify,download,legacyPlan,legacyHistory}){
  let selectedSession=null,selectedDate=today(),planMode=false;
  const state=()=>getState(),trial=()=>activeTrial(state());
  const guard=fn=>{try{return fn();}catch(e){notify(e.message);return null;}};
  function modal(title,html,eyebrow='每日记录'){
    $('dialogTitle').textContent=title;$('dialogEyebrow').textContent=eyebrow;
    $('dialogContent').innerHTML=`<p class="hint" id="journalSave" role="status">填写后自动保存；可以分次补充，空白保留为未填写。</p>${html}`;
    if(!$('exerciseDialog').open)$('exerciseDialog').showModal();$('exerciseDialog').scrollTop=0;
  }
  function save(fn){try{const result=transact(fn);if($('journalSave'))$('journalSave').textContent='已保存本机；登录后联网自动同步';return result;}catch(e){if($('journalSave')){$('journalSave').textContent='保存失败：'+e.message+'。当前输入请先保留。';$('journalSave').className='error';}notify(e.message);return false;}}
  function bindFields(id,kind,initial={}){
    $('dialogContent').querySelectorAll('[data-field]').forEach(el=>{
      el.addEventListener('input',()=>{
        if(!el.checkValidity()){$('journalSave').textContent='输入尚未保存：请填写有效数值或日期。';return;}
        const key=el.dataset.field,value=el.type==='number'?(el.value===''?null:Number(el.value)):el.value;
        if((key==='date'||key==='recoveryDate')&&value&&(!dateOK(value)||value>today())){$('journalSave').textContent='输入尚未保存：实际日期不能晚于今天。';return;}
        save(s=>writeEntry(s,id,kind,{...(entry(s,id)?{}:initial),[key]:value}));
      });
    });
  }
  function openStart(){
    modal('开始两周试行',`<form id="startTrialForm">${input('start','开始日期',today(),'date')}${input('budget','每日饮食预算（元）',30,'number','max="10000"')}<p class="hint">周二、周四同表全身训练，周末一次羽毛球。正式开始后保留阶段和记录；满两周只生成复盘，不自动加量。</p><button class="btn" type="submit">确认开始试行</button></form>`,'两周 · 四次力量训练');
    $('startTrialForm').onsubmit=ev=>{ev.preventDefault();guard(()=>{const start=$('dialogContent').querySelector('[data-field=start]').value,budget=Number($('dialogContent').querySelector('[data-field=budget]').value);transact(s=>startTrial(s,{start,budget}));selectedSession=null;$('exerciseDialog').close();renderPlan();});};
  }
  function chosenSession(){let se=selectedSession&&entry(state(),selectedSession);if(se?.fields.trialId!==trial()?.id)se=null;return se||sessions(state(),trial()?.id).filter(e=>e.fields.date===today()).at(-1)||null;}
  function getOrCreateSession(){let se=chosenSession();if(!se){const id=transact(s=>startSession(s));selectedSession=id;se=entry(state(),id);}return se;}
  function renderPlan(){
    if(planMode){legacyPlan();const back=document.createElement('button');back.className='inline';back.textContent='← 返回两周试行';back.onclick=()=>{planMode=false;renderPlan();};$('main').prepend(back);return;}
    const t=trial(),se=t?chosenSession():null,plan=se?.fields.plan||t?.plan||DEFAULT_PLAN,q=t?trialSummary(state()):null;
    $('main').innerHTML=`<div class="eyebrow">${today()} · 两周试行</div><div class="plan-heading"><h1>今天，练得刚好。</h1><span class="muted">正课 ≤30分钟</span></div><p class="session-hint">周二、周四全身训练 · 周末一次羽毛球</p><section class="card trial-overview">${t?`<div class="row"><b>${t.start} — ${t.end}</b><span class="muted">${today()>t.end?'可复盘／继续观察':today()<t.start?'待开始':'试行中'}</span></div><p class="muted">已有实际训练 ${q.actual.length} 场 · 计划4次 · 预算参考 ${t.budget}元／日</p><button class="btn" id="beginSession">${se?'继续本次训练记录':'记录一次训练'}</button><div class="journal-actions"><button class="inline" id="todayFeedback">每日记录／饮食</button>${se?'<button class="inline" id="newSession">＋ 新建训练场次</button>':''}<button class="inline" id="quickReview">查看阶段复盘</button></div>`:`<h3>先用两周，找到合适的难度。</h3><p class="muted">固定动作，记录实际次数、感受和恢复。旧训练记录继续保留。</p><button class="btn" id="startTrial">开始两周试行</button>`}</section>${se?`<p class="muted">正在记录：${esc(se.fields.date)} · ${label('status',se.fields.status)} <button class="inline" id="sessionFeedback">训练后反馈／次日恢复 →</button></p>`:''}<div class="exercise-grid">${plan.map(e=>{const log=se?entry(state(),exerciseEntryId(se.id,e.id)):null;return `<article class="card"><div class="row start"><span class="name">${esc(e.name)}</span><span class="pill">${log?label('exerciseStatus',log.fields.exerciseStatus):'尚未记录'}</span></div><div class="dose">${e.sets}组 <small>· ${e.sides?'每侧 ':''}${e.min}–${e.max}次</small></div><p class="rest-note">组间休息 ${e.rest===90?'90–120':e.rest}秒 · 目标余力约2–3次</p><details class="exercise-help"><summary>动作要点与版本</summary><p>${esc(e.cue)}<br>${esc(e.variant)} · ${esc(e.load)}</p></details><button class="open" data-journal-exercise="${e.id}">记录这一项 <span>＋</span></button></article>`;}).join('')}</div>${mealGuide()}<details><summary>训练与调整规则</summary><p>热身另计约5分钟：轻活动、肩臂活动和当天动作的轻量练习。达到30分钟就结束，记录未完成原因，不赶动作压缩必要休息。</p><p>初次可调整动作难度。达到次数上限且仍明显轻松，先核对动作和阻力。两次可比较训练都达到上限、仍有余力且恢复正常，再确认是否提高难度；每次只改一个因素。</p><p>周末羽毛球后的酸痛影响周二动作时，顺延或减少相关训练。疼痛与普通酸痛分开记录；明确疼痛停止相关动作，持续或加重需评估。</p><p>弹力带使用前检查裂纹、磨损，按厂家说明固定并遵守拉伸范围，避开尖锐边缘与朝脸回弹的方向。断裂带停用。</p><p>这两周校准难度、时间和恢复；不以两周外观判断增肌效果，不自动增加组数、天数或减少饮食。</p></details><div class="journal-actions">${t?'<button class="inline" id="adjustTrial">调整后续训练安排</button>':''}<button class="inline" id="legacyPlan">查看原训练计划</button></div>`;
    if($('startTrial'))$('startTrial').onclick=openStart;
    if(t){$('beginSession').onclick=()=>guard(()=>{const current=getOrCreateSession();openSession(current.id);});$('todayFeedback').onclick=()=>openDaily(today());$('quickReview').onclick=()=>openReview(t.id);$('adjustTrial').onclick=openAdjust;}
    if(se){$('sessionFeedback').onclick=()=>openSession(se.id);$('newSession').onclick=()=>guard(()=>{selectedSession=transact(s=>startSession(s));openSession(selectedSession);});}
    $('legacyPlan').onclick=()=>{planMode=true;renderPlan();};
    document.querySelectorAll('[data-journal-exercise]').forEach(b=>b.onclick=()=>guard(()=>{if(!trial()){openStart();return;}const current=getOrCreateSession();openExercise(current.id,b.dataset.journalExercise);}));
  }
  function openDaily(date=selectedDate){
    if(!dateOK(date)||date>today()){notify('请选择不晚于今天的有效日期');return;}
    selectedDate=date;const id='daily:'+date,f=entry(state(),id)?.fields||{};
    modal(`${date} · 每日记录`,`${sleepSection(state(),date)}${mealPhotoSection()}${select('feedbackScope','本次反馈覆盖时段',f.feedbackScope,'feedbackScope')}${select('afternoonHunger','下午是否饿（未到下午请留空）',f.afternoonHunger,'afternoonHunger')}${select('digestion','胃肠感受',f.digestion,'digestion')}${select('activity','当天主要活动',f.activity,'activity')}${input('badmintonMinutes','羽毛球时长（分钟，可留空）',f.badmintonMinutes,'number')}${select('hunger','饥饿与饱腹',f.hunger,'hunger')}${select('energy','精神状态',f.energy,'energy')}${select('sleepQuality','昨晚睡眠感受',f.sleepQuality,'sleep')}${input('cost','当天食用成本估算（元）',f.cost,'number')}<details><summary>三餐与份量 · 任选3个代表日详记</summary><p class="hint">普通日、力量训练日、羽毛球日各一次。可写近似份量；注明生／熟、包装总量与实际吃掉多少。</p>${area('breakfast','早餐',f.breakfast)}${area('lunch','午餐',f.lunch)}${area('dinner','晚餐',f.dinner)}${area('foodNotes','加餐、食量与包装说明',f.foodNotes)}${input('purchase','当天采购付款（元，与当天食用成本分开）',f.purchase,'number')}</details><details><summary>咖啡与睡眠补充</summary>${input('coffeeProduct','咖啡产品／规格',f.coffeeProduct)}${input('coffeeTime1','第一杯时间',f.coffeeTime1,'time')}${input('coffeeGrams1','第一杯咖啡粉（克，不确定留空）',f.coffeeGrams1,'number')}${input('coffeeTime2','第二杯时间',f.coffeeTime2,'time')}${input('coffeeGrams2','第二杯咖啡粉（克，不确定留空）',f.coffeeGrams2,'number')}</details><details><summary>可选体重与腰围</summary>${input('weight','体重（kg）',f.weight,'number')}${input('waist','腰围（cm）',f.waist,'number')}${area('measureNotes','测量条件与腰围位置',f.measureNotes,'同一时间、同一位置；不把不同测法直接比较。')}</details>${area('notes','自由补充：感受、问题或临时变化',f.notes)}<button class="btn" id="journalDone">完成本次填写</button>${entry(state(),id)?'<button class="inline" id="deleteDaily">删除这天误建的每日反馈</button>':''}`, '训练、饮食与恢复 · 按日期汇总');
    bindFields(id,'daily',{date});bindMealPhotos({date,getFields:()=>entry(state(),id)?.fields||{},saveFields:fields=>save(s=>writeEntry(s,id,'daily',{date,...fields})),notify});$('journalDone').onclick=()=>$('exerciseDialog').close();if($('deleteDaily'))$('deleteDaily').onclick=()=>{if(!confirm('删除这天的饮食与每日反馈？训练场次和动作记录仍保留。'))return;guard(()=>{transact(s=>removeEntry(s,id));$('exerciseDialog').close();});};
  }
  function openSession(id){
    const se=entry(state(),id);if(!se)return;selectedSession=id;const f=se.fields;
    modal(`${f.date} · 训练后反馈`,`${input('date','实际训练日期（可补记、改日期）',f.date,'date',`max="${today()}"`)}${input('time','实际训练时间（可选）',f.time,'time')}${select('status','本次训练状态',f.status,'status')}${input('minutes','正课实际耗时（分钟）',f.minutes,'number')}${input('sleepHours','训练前一晚睡眠（小时）',f.sleepHours,'number')}${select('pain','本次是否疼痛／明显不适',f.pain,'pain')}${area('painNotes','不适位置、出现在哪个动作',f.painNotes)}${area('reason','未训练、部分完成或提前结束的原因',f.reason)}${area('notes','训练感受与问题',f.notes)}<details><summary>补记／修改这次训练的动作</summary>${f.plan.map(p=>`<button class="btn secondary" data-session-exercise="${p.id}">${esc(p.name)}</button>`).join('')}</details><details id="recoveryFields"><summary>次日恢复反馈 · 可以明天再补</summary>${input('recoveryDate','恢复反馈日期',f.recoveryDate,'date',`max="${today()}"`)}${select('recoveryStatus','恢复与酸痛',f.recoveryStatus,'recovery')}${area('recoveryNotes','部位、持续时间、是否影响活动；近期羽毛球情况',f.recoveryNotes)}</details><button class="btn" id="journalDone">完成本次填写</button><button class="inline" id="deleteSession">删除这次误建的训练场次</button>`,'训练场次 · 可分次填写');
    bindFields(id,'session');$('dialogContent').querySelectorAll('[data-session-exercise]').forEach(b=>b.onclick=()=>openExercise(id,b.dataset.sessionExercise));$('journalDone').onclick=()=>$('exerciseDialog').close();
    $('deleteSession').onclick=()=>{if(!confirm('删除这次场次及其动作记录？删除状态会同步；已有导出备份不受影响。'))return;guard(()=>{transact(s=>{removeEntry(s,id);for(const p of f.plan)removeEntry(s,exerciseEntryId(id,p.id));});selectedSession=null;$('exerciseDialog').close();renderPlan();});};
  }
  function openExercise(sessionId,exerciseId){
    const se=entry(state(),sessionId),plan=se?.fields.plan.find(e=>e.id===exerciseId);if(!plan)return;
    const id=exerciseEntryId(sessionId,exerciseId),f=entry(state(),id)?.fields||{},rows=f.rows||blankRows(plan);
    const rowHTML=(r,i)=>`<fieldset class="set-card"><legend>第${i+1}行${i>=plan.sets?' · 额外一组／同组分段':''}</legend><div class="journal-columns">${plan.sides?`<label>左侧次数<input class="text-input" data-row="${i}" data-key="left" type="number" min="0" max="600" step="1" value="${r.left??''}"></label><label>右侧次数<input class="text-input" data-row="${i}" data-key="right" type="number" min="0" max="600" step="1" value="${r.right??''}"></label>`:`<label>实际次数<input class="text-input" data-row="${i}" data-key="reps" type="number" min="0" max="600" step="1" value="${r.reps??''}"></label>`}<label>还能规范做几次<select class="text-input" data-row="${i}" data-key="rir"><option value="">未填写</option>${Object.entries(LABELS.rir).map(([v,t])=>`<option value="${v}" ${r.rir===v?'selected':''}>${t}</option>`).join('')}</select></label></div><details><summary>本行版本、阻力、休息与动作质量</summary><label class="journal-field">实际动作版本<input class="text-input" data-row="${i}" data-key="variant" maxlength="200" value="${esc(r.variant)}"></label><label class="journal-field">阻力规格／握距<input class="text-input" data-row="${i}" data-key="load" maxlength="200" value="${esc(r.load)}"></label><label class="journal-field">组间休息（秒）<input class="text-input" data-row="${i}" data-key="rest" type="number" min="0" max="600" step="1" value="${r.rest??''}"></label><label class="journal-field">动作质量<select class="text-input" data-row="${i}" data-key="quality"><option value="">未填写</option>${Object.entries(LABELS.quality).map(([v,t])=>`<option value="${v}" ${r.quality===v?'selected':''}>${t}</option>`).join('')}</select></label></details></fieldset>`;
    modal(plan.name,`<p class="muted">${se.fields.date} · 当时目标 ${plan.sets}组 × ${plan.sides?'每侧':''}${plan.min}–${plan.max}次 · 休息${plan.rest}秒左右</p><p class="hint">${esc(plan.cue)} 空白是未填，0是实际做了0次。余力估不准就选“不确定”。</p>${select('exerciseStatus','这个动作的完成情况',f.exerciseStatus,'exerciseStatus')}<div id="trialSetRows">${rows.map(rowHTML).join('')}</div><button class="inline" id="addSetRow">＋ 添加一行：额外组或同组换版本</button><p class="hint">同一组从标准换成跪姿，分别记录两行，在下方注明“第几组分段”。不把不同版本次数相加作进阶依据。</p>${area('notes','动作问题／分段说明／未完成原因',f.notes)}<button class="inline" id="backSession">返回训练后反馈／次日恢复</button><button class="btn" id="journalDone">完成本次填写</button>`,'逐组实际记录');
    bindFields(id,'exercise',{sessionId,exerciseId,rows:copy(rows)});$('backSession').onclick=()=>openSession(sessionId);
    $('dialogContent').querySelectorAll('[data-row]').forEach(el=>el.oninput=()=>{
      if(!el.checkValidity()){$('journalSave').textContent='输入尚未保存：次数与休息需为0–600的整数。';return;}
      const i=Number(el.dataset.row),k=el.dataset.key,v=el.type==='number'?(el.value===''?null:Number(el.value)):el.value;
      save(s=>{const current=entry(s,id)?.fields.rows||copy(rows);const next=copy(current);next[i][k]=v;writeEntry(s,id,'exercise',{sessionId,exerciseId,rows:next});});
    });
    $('addSetRow').onclick=()=>{const current=entry(state(),id)?.fields.rows||rows;if(current.length>=20){notify('最多20行，请在备注补充');return;}if(save(s=>writeEntry(s,id,'exercise',{sessionId,exerciseId,rows:[...copy(current),blankRows({...plan,sets:1})[0]]}))!==false)openExercise(sessionId,exerciseId);};
    $('journalDone').onclick=()=>$('exerciseDialog').close();
  }
  function renderRecords(){
    const t=trial(),list=sessions(state()).filter(e=>e.fields.date===selectedDate);
    const daily=entry(state(),'daily:'+selectedDate),days=Object.values(state().journal?.entries||{}).filter(e=>!e.deleted&&e.kind==='daily').sort((a,b)=>b.fields.date.localeCompare(a.fields.date));
    $('main').innerHTML=`<div class="eyebrow">训练 · 饮食 · 恢复</div><h1>每日记录</h1><button class="inline" id="importSleep">导入三星睡眠 ZIP</button><label class="journal-field">选择日期<input class="text-input" type="date" id="journalDate" value="${selectedDate}" max="${today()}"></label><section class="card"><div class="row"><b>${selectedDate}</b><span class="muted">${daily?'已有每日反馈':'每日反馈未填写'}</span></div>${sleepSection(state(),selectedDate)}<button class="btn" id="editDaily">填写饮食与每日反馈</button>${list.map(e=>`<button class="btn secondary" data-session="${e.id}">训练场次 · ${label('status',e.fields.status)} · ${e.fields.recoveryStatus?'已有恢复反馈':'恢复待补'}</button>`).join('')}${t?'<button class="inline" id="additionalSession">＋ 记录这天的另一次训练</button>':''}</section>${t?`<section class="card"><h3>两周复盘</h3><p class="muted">随时查看，补记后可重新生成。原记录与缺失信息一起保留。</p><select class="text-input" id="reviewTrial">${Object.values(state().journal.trials).sort((a,b)=>b.created.localeCompare(a.created)).map(x=>`<option value="${x.id}" ${x.id===t.id?'selected':''}>${x.start} — ${x.end}</option>`).join('')}</select><button class="btn secondary" id="reviewTrialButton">查看／导出阶段复盘</button></section>`:''}<details><summary>最近的训练与每日反馈</summary>${sessions(state()).slice(-30).reverse().map(e=>`<button class="journal-log" data-session="${e.id}">${esc(e.fields.date)} · 训练 · ${label('status',e.fields.status)}</button>`).join('')}${days.slice(0,30).map(e=>`<button class="journal-log" data-day="${esc(e.fields.date)}">${esc(e.fields.date)} · 饮食与每日反馈</button>`).join('')}</details><div class="journal-actions"><button class="inline" id="legacyHistory">查看原单动作历史</button><button class="inline" id="newTrial">新建下一期试行</button></div>`;
    $('journalDate').onchange=()=>{const value=$('journalDate').value;if(!dateOK(value)||value>today()){notify('请选择有效日期');return;}selectedDate=value;renderRecords();};
    $('editDaily').onclick=()=>openDaily(selectedDate);
    bindSleepImport({state,save,modal,notify,refresh:renderRecords});
    document.querySelectorAll('[data-session]').forEach(b=>b.onclick=()=>{selectedSession=b.dataset.session;openSession(selectedSession);});
    document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>openDaily(b.dataset.day));
    if(t){$('additionalSession').onclick=()=>guard(()=>{selectedSession=transact(s=>startSession(s,{date:selectedDate}));openSession(selectedSession);});$('reviewTrialButton').onclick=()=>openReview($('reviewTrial').value);}
    $('legacyHistory').onclick=()=>{legacyHistory();const back=document.createElement('button');back.className='inline';back.textContent='← 返回每日记录';back.onclick=renderRecords;$('main').prepend(back);};$('newTrial').onclick=openStart;
  }
  function openReview(id){
    const q=trialSummary(state(),id),text=trialMarkdown(state(),id);
    modal('两周试行复盘',`<p class="muted">${q.trial.start} — ${q.trial.end} · 实际训练${q.actual.length}场 · ${q.actual.length<4?'记录尚不足4场，可继续观察':'结合动作与恢复决定下一步'}</p><button class="btn" id="downloadTrialPhotos">导出复盘＋照片 ZIP</button><button class="btn secondary" id="downloadTrial">仅导出文字 Markdown</button><button class="btn secondary" id="copyTrial">复制复盘全文</button><pre class="review-preview">${esc(text)}</pre>`,'事实、缺失与待确认调整');
    $('downloadTrialPhotos').onclick=async()=>{const b=$('downloadTrialPhotos');b.disabled=true;b.textContent='正在整理记录和照片…';try{const data=await mealArchive({from:q.trial.start,to:q.to,markdown:trialMarkdown(state(),id)});if(data)download(`两周复盘含照片-${q.trial.start}.zip`,data,'application/zip');}catch(e){notify(e.message);}finally{b.disabled=false;b.textContent='导出复盘＋照片 ZIP';}};$('downloadTrial').onclick=()=>download(`两周试行复盘-${q.trial.start}.md`,trialMarkdown(state(),id),'text/markdown;charset=utf-8');$('copyTrial').onclick=async()=>{try{await navigator.clipboard.writeText(trialMarkdown(state(),id));notify('复盘全文已复制');}catch{notify('复制不可用，请导出Markdown');}};
  }
  function openAdjust(){
    const t=trial();if(!t)return;
    modal('调整后续训练安排',`<form id="adjustTrialForm"><p class="hint">仅影响以后新建的场次，已开始场次和旧记录保留当时目标。每次只调整需要改变的因素，不因两周结束自动加量。</p>${t.plan.map((p,i)=>`<details><summary>${esc(p.name)}</summary><div class="journal-columns">${input(i+'-sets','组数',p.sets,'number','min="1" max="6" step="1"')}${input(i+'-min','次数下限',p.min,'number','min="1" max="100" step="1"')}${input(i+'-max','次数上限',p.max,'number','min="1" max="100" step="1"')}</div>${input(i+'-variant','动作版本',p.variant)}${input(i+'-load','阻力／握距',p.load)}</details>`).join('')}${area('reason','本次调整原因（必填）','')}<button class="btn" type="submit">确认调整后续安排</button></form>`,'本人确认 · 历史保留');
    $('adjustTrialForm').onsubmit=ev=>{ev.preventDefault();guard(()=>{const form=$('adjustTrialForm'),value=k=>form.querySelector(`[data-field="${k}"]`).value,plan=t.plan.map((p,i)=>({...p,sets:Number(value(i+'-sets')),min:Number(value(i+'-min')),max:Number(value(i+'-max')),variant:value(i+'-variant'),load:value(i+'-load')}));transact(s=>changePlan(s,plan,value('reason')));$('exerciseDialog').close();renderPlan();notify('后续安排已调整，既有场次保持原快照');});};
  }
  function photoBackupSection(){return `<section class="card"><h3>餐次照片备份</h3><p class="muted">ZIP包含照片、照片清单和文字记录JSON。离线只能导出本机已缓存的照片。解压后可把复盘Markdown和photos文件夹一起放入Obsidian。</p><button class="btn secondary" id="exportMealBackup">导出照片与记录 ZIP</button><label class="btn secondary file-label">从ZIP恢复照片<input type="file" id="restoreMealBackup" accept=".zip,application/zip"></label><p class="hint">此恢复入口只恢复照片；文字记录用下方JSON入口恢复。清除浏览器数据前先备份待同步照片。</p></section>`;}
  function bindPhotoBackup(){
    $('exportMealBackup').onclick=async()=>{const b=$('exportMealBackup');b.disabled=true;try{const data=await mealArchive({markdown:trial()?trialMarkdown(state()):'# 饮食照片记录\n',records:state()});if(data)download(`训练卡照片与记录-${today()}.zip`,data,'application/zip');}catch(e){notify(e.message);}finally{b.disabled=false;}};
    $('restoreMealBackup').onchange=async ev=>{const file=ev.target.files[0];if(!file)return;try{const n=await restoreMealArchive(file);if(n!==undefined)notify(`已处理${n}张照片；未联网时等待同步`);}catch(e){notify(e.message);}finally{ev.target.value='';}};
  }
  function exportSection(){const t=trial();return photoBackupSection()+(t?`<section class="card"><h3>两周试行复盘</h3><p class="muted">训练、饮食、恢复与未填写信息统一导出，支持Obsidian与后续分析。</p><button class="btn" id="settingsTrialReview">查看／导出两周复盘</button></section>`:'');}
  function bindExport(){bindPhotoBackup();if($('settingsTrialReview'))$('settingsTrialReview').onclick=()=>openReview(trial().id);}
  $('exerciseDialog').addEventListener('close',()=>{document.dispatchEvent(new Event('training:journal-close'));});
  return {renderPlan,renderRecords,exportSection,bindExport};
}
